// Concatenates every migration of supabase/migrations (in order) into supabase/setup.sql: one
// file the owner can paste into the Supabase SQL Editor to set up a fresh project.
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

export function sqlBundle(root) {
  const dir = join(root, 'supabase', 'migrations');
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.sql'))
    .sort();
  const parts = files.map(
    (f) => `-- ===== ${f} =====\n\n${readFileSync(join(dir, f), 'utf8').trim()}\n`,
  );
  return [
    '-- Kiwar: full database setup for a NEW Supabase project (generated by `pnpm build:sql`).',
    '-- Paste everything into the SQL Editor and click Run. For an existing project, run only',
    '-- the migrations added since your last setup (see docs/SUPABASE_SETUP.md).',
    '',
    ...parts,
  ].join('\n');
}

export const sqlBundlePath = (root) => join(root, 'supabase', 'setup.sql');
